-- Agrega clientes.numero_cliente (el "CLIENTE,N,4,0" del FoxPro original,
-- ver tools/importar_clientes.py) y lo rellena para los clientes que ya
-- existían. Generado con tools/generar_numero_cliente.py — no se edita a
-- mano, se vuelve a correr ese script si hace falta regenerarlo.
--
-- Dos pasadas: primero los 8645 del catálogo de FoxPro, con su mismo id
-- determinista en cualquier instalación; luego cualquier cliente que ya
-- existiera antes de ese catálogo (distinto en cada caja) recibe el
-- siguiente consecutivo después de 8645, en el orden en que se dio de
-- alta. Ver el docstring de tools/generar_numero_cliente.py para el porqué
-- de cada parte.

ALTER TABLE clientes ADD COLUMN numero_cliente INTEGER;

