-- Clientes que ya estaban antes del catálogo (dados de alta a mano): no hay
-- forma de saber su id de antemano, así que se les asigna el siguiente
-- consecutivo después de 8645, en el orden en que se dieron de alta.
--
-- El `WITH` se resuelve una sola vez, ANTES de que el UPDATE toque ninguna
-- fila: es la foto fija que hace falta para numerar bien. La primera versión
-- de esta migración calculaba el rango con una subconsulta correlacionada
-- que leía `numero_cliente IS NULL` de la MISMA tabla que iba mutando —con
-- dos o más clientes manuales, el UPDATE ya había apagado el NULL del
-- primero para cuando le tocaba al segundo, y los dos terminaban con el
-- mismo número (se cayó el índice único al probarlo con dos clientes
-- manuales de prueba, antes de que esto llegara a producción).
WITH faltantes AS (
    SELECT id, ROW_NUMBER() OVER (ORDER BY creado_en, id) AS posicion
      FROM clientes
     WHERE numero_cliente IS NULL
)
UPDATE clientes
   SET numero_cliente = 8645 + faltantes.posicion
  FROM faltantes
 WHERE clientes.id = faltantes.id;

CREATE UNIQUE INDEX ix_clientes_numero_cliente ON clientes(numero_cliente);
